public class IdGeneratorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        IdGenerator.resetCounter();

        IdGenerator a = new IdGenerator("user");
        check("first instance", "user-1", a.getId());

        IdGenerator b = new IdGenerator("user");
        check("second instance", "user-2", b.getId());

        IdGenerator c = new IdGenerator("order");
        check("counter shared across prefixes", "order-3", c.getId());

        check("an id never changes", "user-1", a.getId());
        check("earlier instance keeps its id too", "user-2", b.getId());

        IdGenerator.resetCounter();
        IdGenerator d = new IdGenerator("user");
        check("resetCounter starts over at 1", "user-1", d.getId());
        check("old instances survive a reset", "order-3", c.getId());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

