public class IdGenerator {

    private static int counter = 0;

    private String id;

    public IdGenerator(String prefix) {
        counter++;
        this.id = prefix + "-" + counter;
    }

    public String getId() {
        return id;
    }

    public static void resetCounter() {
        counter = 0;
    }
}
